// 面板／核心「自產」UI 文字（分頁名、標籤、狀態字樣等）三語字典。
//
// 跟 utils/gamedata-i18n.ts 的分工：那邊是「遊戲資料」（艦名／裝備名）的譯名表，
// 刻意留空待外部工具填入；這裡是我們自己撰寫、現在就要上線的介面文字，三語直接
// 內建、不留白。玩法上的判斷（rank、關卡量表、燃彈…）邏輯完全不受影響，這裡純粹
// 是顯示字串的替換。
//
// 語言狀態單一入口：跟 gamedata-i18n.ts 共用同一個 Lang、同一次 setLang() 呼叫，
// 呼叫端（面板）不必分別呼叫兩個 setter。持久化（localStorage）、瀏覽器語言偵測留在
// 面板層（entrypoints/panel/main.ts），這裡只放記憶體變數＋純函式，讓 state.ts
// 可繼續獨立編譯、用 node 餵封包測試（AGENTS.md 硬約束 6：核心零瀏覽器依賴）。
import { setDisplayLang, type Lang } from './gamedata-i18n';
import { THEATER_STRINGS } from './theater-i18n';

export { LANGS } from './lang';

let lang: Lang = 'ja';
export function getLang(): Lang { return lang; }
export function setLang(l: Lang) { lang = l; setDisplayLang(l); }

type Dict = Record<string, string>;

