        'ov.backupIntro': '匯出成可完整還原的結構化 JSON：目前狀態、各類紀錄、出擊明細、任務導覽的釘選／人工完成、不記錄的海域設定，以及本機觀測到的任務領獎會放在同一個檔案。還原只支援尚未開始本機擷取、且匯入檔案所對應的目標資料表皆為空的環境；不會合併或覆寫既有資料。符合條件時，即使把擴充完全解除安裝再重裝，匯入後總括頁也能立刻重建艦娘/裝備/艦隊/完整出擊與工廠紀錄，不必等重新登入遊戲。（跟「LLM 分析」的完整報告不同：那份是給人/LLM 讀的精簡摘要，不能拿來匯入還原。）',
