        'ov.backup': 'バックアップと復元',
        'ov.backupIntro': '現在の状態、各種記録、出撃の詳細、任務ナビのピン留め／手動完了、記録しない海域の設定、および任務報酬受け取りの観測記録を一つにまとめた、完全復元可能な構造化JSONをエクスポートします。復元に対応するのは、ローカル取得をまだ開始しておらず、インポートするファイルの対象テーブルがすべて空の環境だけです。既存データのマージや上書きは行いません。条件を満たせば、拡張機能を完全にアンインストールして再インストールしても、インポート後すぐに艦娘/装備/艦隊/完全な出撃・工廠記録を再構築でき、ゲームに再ログインする必要はありません（「LLM分析」の完全レポートとは別物：あちらは人間/LLM向けの簡易サマリで、インポート復元には使えません）。',
        'ov.backupExport': 'バックアップをエクスポート (.json)', 'ov.backupImport': 'バックアップをインポート (.json)',
        'ov.backupExported': 'エクスポート完了、{file}、{n}件。',
        'ov.backupBadFile': 'バックアップファイルの形式が不正、またはバージョンに互換性がありません。データはインポートされませんでした。',
        'ov.backupNeedComplement': '旧版の分割バックアップを1つ読み込みました。もう一度「バックアップをインポート」を押して、もう一方のファイルを選択してください。2つ揃うまでデータは書き込まれません。',
        'ov.backupVersionMismatch': 'バックアップファイルのバージョンが一致しません。互換性のない拡張機能バージョンの可能性があります。',
        'ov.backupConfirm': '{n}件のレコードをインポートします（バックアップ日時：{date}）。復元は、ローカル取得をまだ開始しておらず、このファイルの対象テーブルが空の環境のみ対応します。条件を満たさない場合はデータを変更せず拒否されます。続行しますか？',
        'ov.backupDestinationNotEmpty': 'インポートできません：この復元環境にはローカル取得／投影履歴があるか、このファイルの対象テーブルに既存データがあります。バックアップの復元は、ローカル取得をまだ開始しておらず、対象テーブルが空の環境のみ対応します。既存データは変更されていません。',
        'ov.backupImporting': 'インポート中…',
