        'ov.backupFolderTitle': 'フォルダバックアップ（同期フォルダへ書き込み）',
        'ov.backupFolderIntro': 'フォルダを選ぶと（Google Drive Desktop、WebDAVマウントしたネットワークドライブ、Dropbox等の同期フォルダを指定可）、拡張機能が「完全バックアップ＋オフライン抽出ツール viewer.html」を一括で書き込みます。クラウド同期はデスクトップ同期クライアントが担当し、拡張機能はネットワークに接続せず、新たな権限も不要です。毎回新しいファイルになります（ファイル名に日付と時刻）。新規インストールでデータが無いときは書き込みません（空ファイルで旧バックアップを上書きしないため）。',
