        'ov.backupFileTitle': 'ファイルエクスポート／インポート',
        'ov.backupFileIntro': '既定では、母港スナップショット、各種記録、保持中の出撃生データ、任務ナビのピン留め／手動完了、記録しない海域の設定を含む一つの完全バックアップをエクスポートします。復元後は出撃編成と各ノードの詳細を直接確認できます。旧版の分割ファイルも移行可能です。kanmusu-restore.json と kanmusu-replays.json を同時に選ぶか、一方を選んだ後にもう一度「バックアップをインポート」を押してもう一方を選択してください。2つ揃ってから一括で検証・復元します。各インポートはローカル取得開始前かつ対象テーブルが空の環境でのみ実行できます。',
