        'ov.resourceLog': 'Resource Log',
        'ov.rlIntro': 'A time series of resource balances. The game only reports "how much is left now", so any "how much was spent" is the difference between two balances — every delta here therefore names the period it covers. Sampling happens on every return to port (api_port/port) and continues while the panel is closed.',
