        'ov.rlSummaryOne': '{n} samples　{from}',
        'ov.rlChartNote': 'Click the legend to show or hide individual resources. The y-axis scales to the visible resources only — fuel runs in the hundred-thousands while screws run in the thousands, so hide the bulk resources and the remaining lines expand to fill the chart. Hover anywhere on the chart for every visible value at that moment.',
