        'ov.rlBasicNote': 'Unattributed = closing − opening − regen − income − en route + spending, and can be positive or negative. Sources not broken out yet — dismantling, scrapping, modernization, medal exchanges and so on — all land in this column. Resupply and repairs are paid after returning to port, so a short period shows some timing offset. The recovery cap uses your current HQ level and runs high for periods before a level-up. En-route changes include natural recovery during sorties, which overlaps the regen column, so unattributed runs slightly low.',
