        'ov.rlGain': 'gain', 'ov.rlDrain': 'spent',
        'ov.backup': 'Backup & Restore',
        'ov.backupIntro': "Export one complete, restorable structured JSON backup containing current state, every log, sortie detail, quest-guide pins / manual-complete marks, the maps-not-logged setting, and locally observed quest reward claims. Restore is supported only when local capture has not started and every target table for the imported file is empty; existing data is never merged or overwritten. When those conditions are met, even after fully uninstalling and reinstalling the extension, an import lets the overview page immediately rebuild your ships/equipment/fleets/full sortie & factory records without waiting to log back into the game. (Different from the \"LLM Analysis\" full report — that one is a compact human/LLM-readable summary and cannot be imported to restore.)",
        'ov.backupExport': 'Export Backup (.json)', 'ov.backupImport': 'Import Backup (.json)',
        'ov.backupExported': 'Exported {file} — {n} records.',
        'ov.backupBadFile': 'The backup file is malformed or uses an incompatible version. No data was imported.',
        'ov.backupNeedComplement': 'One legacy split backup was read. Click Import Backup again and select its companion file. No data is written until both files are present.',
        'ov.backupVersionMismatch': 'Backup file version mismatch — it may be from an incompatible extension version.',
        'ov.backupConfirm': 'About to import {n} records (backed up: {date}). Restore is supported only before local capture begins and while this file\'s target tables are empty; otherwise the import will be refused without changing data. Continue?',
        'ov.backupDestinationNotEmpty': 'Import refused: this restore environment already has local capture/projection history, or this file\'s target tables contain data. Backup restore is supported only before local capture begins and while the target tables are empty. Existing data was not changed.',
        'ov.backupImporting': 'Importing…',
        'ov.backupImported': 'Import complete — wrote {n} records, view refreshed to the latest state.',
        'ov.backupImportError': 'Import failed: {msg}',
        'ov.backupEmptyRefuse': 'Nothing to back up yet. No file was written, so an empty save cannot overwrite an older backup in the folder.',
        'ov.backupFolderTitle': 'Folder backup (write to a synced folder)',
        'ov.backupFolderIntro': "Pick a folder (point it at a synced folder like Google Drive Desktop, a WebDAV-mounted network drive, Dropbox, etc.) and the extension writes the complete backup + offline extractor viewer.html into it at once. Cloud sync is handled by your desktop sync client; the extension never touches the network and needs no new permissions. Each backup is a new file (the name includes date and time). A fresh install with no data will not write a file, so an empty save cannot overwrite an older backup in the folder.",
        'ov.backupPickFolder': 'Choose folder…', 'ov.backupToFolder': 'Back up to folder', 'ov.backupForgetFolder': 'Forget folder',
        'ov.backupFolderCurrent': 'Current folder: {name}', 'ov.backupFolderNone': 'No folder chosen yet.',
        'ov.backupFolderDenied': 'Write permission for the folder was not granted.', 'ov.backupWriting': 'Writing…',
        'ov.backupWrittenTo': 'Backed up to "{name}" as {file} — {n} records (viewer.html also updated).',
        'ov.backupWriteError': 'Write failed: {msg}',
        'ov.backupNoFsa': 'This browser does not support folder writing (File System Access API). Please use the file export/import below.',
        'ov.backupFileTitle': 'File export / import',
        'ov.backupFileIntro': 'The default export is one complete backup containing home-port snapshots, every log, all retained raw battle data, quest-guide pins / manual-complete marks, and the maps-not-logged setting, so restored sorties retain their fleets and per-node details. To migrate an older split backup, select kanmusu-restore.json and kanmusu-replays.json together, or select one and click Import Backup again to select the other; validation and restore begin only after both files are present. Each import still requires that local capture has not started and that the target tables are empty.',
        'ov.retentionTitle': 'Replay pruning (manage file size)',
        'ov.retentionIntro': 'The replay layer grows with sortie count. Key sorties are protected (new-ship drop / gauge break / event boss / maps still in progress / manual ★ pin); the rest keep only recent sorties within the window. Pruning removes only replay data — sortie summaries stay.',
        'ov.retNewShip': 'Keep new-ship drops forever', 'ov.retCleared': 'Keep gauge-break sorties forever',
        'ov.retEventBoss': 'Keep event boss sorties forever', 'ov.retUncleared': 'Keep all sorties on uncleared maps',
