        'ov.reportSectionTitle': 'HQ Overview',
        'ov.reportIntro': 'Compile your HQ status into one Markdown report — the full ship roster grouped by ship type, all equipment grouped by category, a resource inventory, and sortie records from the last six months. Paste it into or upload it to any mainstream LLM (Claude.ai, ChatGPT, Gemini, etc). Runs entirely locally, needs no extra permission — whether the data ever leaves your machine is entirely up to whether you choose to hand this file to something.',
